const ARRAYS=['expenses','uberEntries','incomes','priorities','investments','dividends','trips','tripItems','debts','debtPayments','creditCards','cardPurchases','cardInvoices','calendarEvents','profiles'];
const MAPS=['dailyEarnings','dailyActive','monthSettings'];
const STORAGE={config:'nexo-pwa-config-v1',snapshot:'nexo-pwa-snapshot-v1',profile:'nexo-pwa-profile-v1'};
const state={tab:'home',morePage:'hub',data:{},config:{},profileId:null,status:'Local',assistant:[]};
const n=v=>Number(String(v??'').replace(',','.'))||0;
const round2=v=>Math.round((n(v)+Number.EPSILON)*100)/100;
const uuid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const todayKey=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:state.data.settings?.currency||'BRL'}).format(n(v));
const monthKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
const addMonths=(ref,delta)=>{const [y,m]=ref.split('-').map(Number),d=new Date(y,m-1+delta,1);return monthKey(d)};
function normalizeUrl(v){return String(v||'').trim().replace(/\/rest\/v1\/?$/i,'').replace(/\/$/,'')}
function configProblems(c){const p=[];const u=normalizeUrl(c?.supabaseUrl);if(!u)p.push('Project URL');else{try{const x=new URL(u);if(x.protocol!=='https:')p.push('Project URL (precisa usar https)')}catch{p.push('Project URL inválida')}}if(!String(c?.anonKey||'').trim())p.push('Anon / Public Key');if(!String(c?.householdId||'').trim())p.push('ID da família');if(!String(c?.accessKey||'').trim())p.push('Chave da família');return p}
function validConfig(c){return configProblems(c).length===0}
function headers(c){return {'apikey':String(c.anonKey).trim(),'x-family-key':String(c.accessKey).trim(),'x-household-id':String(c.householdId).trim(),'Content-Type':'application/json',Authorization:`Bearer ${String(c.anonKey).trim()}`}}
async function req(route,opts={}){const c=state.config;const r=await fetch(`${normalizeUrl(c.supabaseUrl)}/rest/v1/${route}`,{...opts,headers:{...headers(c),...(opts.headers||{})}});const t=await r.text();let b;try{b=t?JSON.parse(t):null}catch{b=t}if(!r.ok){const detail=b?.message||b?.hint||b?.details||t||`HTTP ${r.status}`;throw new Error(`${detail} (HTTP ${r.status})`)}return b}
async function pullAll(){const household=encodeURIComponent(String(state.config.householdId).trim());const rows=await req(`finance_records?household_id=eq.${household}&select=record_type,record_id,payload,updated_at&order=updated_at.asc`);const data={};ARRAYS.forEach(k=>data[k]=[]);MAPS.forEach(k=>data[k]={});for(const r of rows||[]){if(ARRAYS.includes(r.record_type))data[r.record_type].push(r.payload);else if(MAPS.includes(r.record_type))data[r.record_type][r.record_id]=r.payload;else if(r.record_type==='$root')data[r.record_id]=r.payload}return data}
async function upsert(type,id,payload,{resync=true}={}){const c=state.config;const row={household_id:String(c.householdId).trim(),access_key:String(c.accessKey).trim(),record_type:type,record_id:String(id),payload,updated_at:new Date().toISOString()};await req('finance_records?on_conflict=household_id,record_type,record_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify([row])});if(resync)await sync(true)}
async function removeRecord(type,id){const household=encodeURIComponent(String(state.config.householdId).trim()),rid=encodeURIComponent(String(id));await req(`finance_records?household_id=eq.${household}&record_type=eq.${encodeURIComponent(type)}&record_id=eq.${rid}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await sync(true)}
function saveLocal(){localStorage.setItem(STORAGE.snapshot,JSON.stringify(state.data));localStorage.setItem(STORAGE.config,JSON.stringify(state.config));if(state.profileId)localStorage.setItem(STORAGE.profile,state.profileId)}
function loadLocal(){try{state.data=JSON.parse(localStorage.getItem(STORAGE.snapshot)||'{}');state.config=JSON.parse(localStorage.getItem(STORAGE.config)||'{}');state.profileId=localStorage.getItem(STORAGE.profile)}catch{}}
async function sync(silent=false){const missing=configProblems(state.config);if(missing.length){state.status='Local';render();if(!silent)alert(`Falta configurar: ${missing.join(', ')}.`);return false}setSyncing(true);try{state.data=await pullAll();state.status='Sincronizado';saveLocal();return true}catch(e){state.status='Erro de conexão';if(!silent)alert(`Falha na sincronização:\n${e.message}`);return false}finally{setSyncing(false);render()}}
function setSyncing(on){document.getElementById('syncBtn')?.classList.toggle('spin',on)}
function activeProfile(){const ps=state.data.profiles||[];return ps.find(p=>String(p.id)===String(state.profileId))||ps[0]||null}
function recordMeta(extra={}){const p=activeProfile();return {...extra,ownerProfileId:extra.ownerProfileId??p?.id??null,createdByProfileId:extra.createdByProfileId??p?.id??null,updatedByProfileId:p?.id??null,createdAt:extra.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()}}
function monthSummary(date=new Date()){const mk=monthKey(date);const uber=(state.data.uberEntries||[]).filter(e=>String(e.date||'').slice(0,7)===mk&&e.active!==false);const gross=uber.reduce((s,e)=>s+n(e.value),0),fuel=uber.reduce((s,e)=>s+n(e.fuelExpense),0),reserved=uber.reduce((s,e)=>s+n(e.reserveValue??n(e.value)*n(e.reservePercent)/100),0);const other=(state.data.incomes||[]).filter(e=>String(e.date||e.data||'').slice(0,7)===mk).reduce((s,e)=>s+n(e.value??e.valor),0);const regular=(state.data.expenses||[]).filter(e=>String(e.date||e.data||'').slice(0,7)===mk).reduce((s,e)=>s+n(e.value??e.valor),0);const income=gross+other,expenses=regular+fuel;const pending=(state.data.priorities||[]).filter(p=>String(p.dataVencimento||'').slice(0,7)===mk||String(p.mesReferencia||'')===mk||`${p.anoReferencia}-${String(p.mesReferencia).padStart(2,'0')}`===mk).reduce((s,p)=>s+Math.max(n(p.valorPrevisto)-n(p.valorPago),0),0);const after=income-expenses-pending-reserved,planned=Math.max(after,0)*n(state.data.settings?.investPercent)/100;return{mk,income,expenses,result:income-expenses,free:after-planned,pending,reserved,planned,gross,fuel,km:uber.reduce((s,e)=>s+n(e.kmDriven),0)}}
function movementRows(date=new Date()){const mk=monthKey(date),rows=[];for(const e of state.data.uberEntries||[]){if(String(e.date||'').slice(0,7)!==mk||e.active===false)continue;rows.push({date:e.date,label:'Uber',kind:'income',value:n(e.value)});if(n(e.fuelExpense))rows.push({date:e.date,label:'Combustível Uber',kind:'expense',value:n(e.fuelExpense)})}for(const e of state.data.incomes||[]){if(String(e.date||e.data||'').slice(0,7)===mk)rows.push({date:e.date||e.data,label:e.description||e.descricao||e.category||e.categoria||'Entrada',kind:'income',value:n(e.value??e.valor)})}for(const e of state.data.expenses||[]){if(String(e.date||e.data||'').slice(0,7)===mk)rows.push({date:e.date||e.data,label:e.description||e.descricao||e.category||e.categoria||'Saída',kind:'expense',value:n(e.value??e.valor)})}return rows.sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function shell(title,sub,body){return `<h1 class="page-title">${title}</h1><p class="subtitle">${sub}</p>${body}`}
function kpi(label,value,cls='cyan'){return `<div class="card kpi"><div class="label">${label}</div><div class="value ${cls}">${value}</div></div>`}
function row(a,b,cls=''){return `<div class="row"><span>${a}</span><strong class="${cls}">${b}</strong></div>`}
function empty(t){return `<div class="empty">${t}</div>`}
function back(){return `<button class="back-link" data-more="hub">‹ Mais</button>`}
function renderHome(){const m=monthSummary();return shell('Visão Geral','Seu mês em uma leitura rápida',`<div class="grid">${kpi('Entradas',money(m.income),'green')}${kpi('Saídas',money(m.expenses),'pink')}${kpi('Resultado',money(m.result),m.result>=0?'cyan':'pink')}${kpi('Livre de verdade',money(m.free),'purple')}</div><section class="card"><h2 class="section-title">Compromissos</h2>${row('Prioridades pendentes',money(m.pending))}${row('Separado no Uber',money(m.reserved))}${row('Investimento planejado',money(m.planned))}</section><section class="card"><h2 class="section-title">Uber do mês</h2>${row('Bruto',money(m.gross))}${row('Combustível',money(m.fuel))}${row('KM',`${m.km.toFixed(1)} km`)}</section>`)}
function renderMoves(){const rows=movementRows();return shell('Movimentos','Entradas e saídas reais do mês',`<section class="card">${rows.length?rows.map(r=>`<div class="movement"><div class="main"><strong>${esc(r.label)}</strong><small>${esc(r.date)}</small></div><div class="amount ${r.kind==='income'?'green':'pink'}">${r.kind==='income'?'+':'−'} ${money(r.value)}</div></div>`).join(''):empty('Nenhuma movimentação neste mês.')}</section><section class="card"><h2 class="section-title">Novo lançamento</h2><form id="movementForm" class="form"><div class="field"><label>Tipo</label><select name="type"><option value="expense">Saída</option><option value="income">Entrada</option></select></div><div class="field"><label>Descrição</label><input name="description" required></div><div class="field"><label>Valor</label><input name="value" inputmode="decimal" required></div><div class="field"><label>Data</label><input name="date" type="date" value="${todayKey()}" required></div><button class="btn">Salvar e sincronizar</button></form></section>`)}
function renderUber(){const date=todayKey(),e=(state.data.uberEntries||[]).find(x=>x.date===date)||{};return shell('Uber','Lançamento rápido do dia',`<section class="card"><form id="uberForm" class="form"><div class="field"><label>Data</label><input name="date" type="date" value="${esc(e.date||date)}"></div><div class="field"><label>Ganho bruto</label><input name="gross" inputmode="decimal" value="${esc(e.value||'')}"></div><div class="grid"><div class="field"><label>Combustível</label><input name="fuel" inputmode="decimal" value="${esc(e.fuelExpense||'')}"></div><div class="field"><label>KM rodados</label><input name="km" inputmode="decimal" value="${esc(e.kmDriven||'')}"></div></div><div class="field"><label>% para separar</label><input name="pct" inputmode="decimal" value="${esc(e.reservePercent??state.data.settings?.uberReservePercent??0)}"></div><button class="btn">Salvar Uber</button></form></section>`)}
function parseAssistant(text){const lower=text.toLowerCase(),match=text.match(/(?:r\$\s*)?(\d+(?:[.,]\d{1,2})?)/);if(!match)return{error:'Não encontrei um valor. Ex.: “gastei 35 no almoço hoje”.'};const value=n(match[1]),date=lower.includes('ontem')?(()=>{const d=new Date();d.setDate(d.getDate()-1);return monthKey(d)+'-'+String(d.getDate()).padStart(2,'0')})():todayKey();if(/recebi|ganhei|entrada|salário|salario/.test(lower))return{type:'income',value,date,description:text.replace(match[0],'').trim()||'Entrada'};return{type:'expense',value,date,description:text.replace(match[0],'').trim()||'Saída'}}
function renderAssistant(){return shell('Assistente','Descreva a movimentação do seu jeito',`<div class="assistant-log">${state.assistant.map(m=>`<div class="bubble ${m.role}">${esc(m.text)}</div>`).join('')}</div><section class="card"><form id="assistantForm" class="form"><div class="field"><label>Mensagem</label><textarea name="text" placeholder="Ex.: gastei 35 no almoço hoje"></textarea></div><button class="btn">Interpretar</button></form></section>`)}
function hubItem(page,icon,title,desc){return `<button class="hub-item" data-more="${page}"><img src="assets/icons/${icon}.svg" alt=""><span><strong>${title}</strong><small>${desc}</small></span><b>›</b></button>`}
function renderMoreHub(){return shell('Mais','Planejamento, patrimônio e sincronização',`<section class="hub">${hubItem('cards','credit-card','Cartões','Faturas, compras e limite')}${hubItem('reports','file-chart-column-increasing','Relatórios','Tendências e categorias')}${hubItem('priorities','siren','Prioridades','Reservas e compromissos')}${hubItem('investments','chart-no-axes-combined','Investimentos','Patrimônio e rendimentos')}${hubItem('debts','badge-dollar-sign','Dívidas','Saldo e pagamentos')}${hubItem('trips','plane','Viagens','Orçamento e reservas')}${hubItem('calendar','calendar','Calendário','Vencimentos e lembretes')}${hubItem('profile','user','Perfil',activeProfile()?.name||activeProfile()?.nome||'Escolher perfil')}${hubItem('settings','settings','Configurações','Supabase e conexão')}</section>`)}
function renderPriorities(){const ref=monthKey(),list=(state.data.priorities||[]).filter(x=>String(x.dataVencimento||'').slice(0,7)===ref||String(x.mesReferencia||'')===ref||`${x.anoReferencia}-${String(x.mesReferencia).padStart(2,'0')}`===ref);const pending=list.reduce((s,x)=>s+Math.max(n(x.valorPrevisto)-n(x.valorPago),0),0);return `${back()}${shell('Prioridades','Compromissos antes do dinheiro livre',`<div class="grid">${kpi('Pendentes',money(pending),'pink')}${kpi('Itens',String(list.length),'cyan')}</div><section class="card">${list.length?list.map(x=>`${row(esc(x.nome||'Prioridade'),money(Math.max(n(x.valorPrevisto)-n(x.valorPago),0)),Math.max(n(x.valorPrevisto)-n(x.valorPago),0)>0?'pink':'green')}<div class="mini-meta">${esc(x.dataVencimento||'Sem vencimento')} · ${esc(x.nivelPrioridade||'')}</div>`).join(''):empty('Nenhuma prioridade neste mês.')}</section><section class="card"><h2 class="section-title">Nova prioridade</h2><form id="priorityForm" class="form"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Valor previsto</label><input name="value" inputmode="decimal" required></div><div class="field"><label>Vencimento</label><input name="due" type="date" value="${todayKey()}"></div><button class="btn">Salvar prioridade</button></form></section>`)}`}
function investmentSummary(inv){const q=n(inv.quantidade);const invested=n(inv.valorInvestido)||(q*n(inv.precoMedio));const current=n(inv.valorAtual)||(q*n(inv.valorAtualUnitario));return{invested,current}}
function renderInvestments(){const list=(state.data.investments||[]).filter(x=>x.ativo!==false),divs=state.data.dividends||[];let invested=0,current=0;list.forEach(x=>{const s=investmentSummary(x);invested+=s.invested;current+=s.current});const yields=divs.reduce((s,d)=>s+n(d.valor),0);return `${back()}${shell('Investimentos','Patrimônio e rendimentos',`<div class="grid">${kpi('Investido',money(invested),'cyan')}${kpi('Atual',money(current),'green')}${kpi('Resultado',money(current-invested),current>=invested?'green':'pink')}${kpi('Rendimentos',money(yields),'purple')}</div><section class="card">${list.length?list.map(x=>{const s=investmentSummary(x);return `${row(esc(x.nome||x.ticker||'Investimento'),money(s.current),'cyan')}<div class="mini-meta">${esc(x.ticker||x.tipo||'')} · investido ${money(s.invested)}</div>`}).join(''):empty('Nenhum investimento cadastrado.')}</section><section class="card"><h2 class="section-title">Novo investimento</h2><form id="investmentForm" class="form"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Ticker</label><input name="ticker"></div><div class="field"><label>Tipo</label><select name="type"><option>FII</option><option>Ação</option><option>ETF</option><option>Tesouro Direto</option><option>CDB</option><option>Criptomoeda</option><option>Outro</option></select></div><div class="field"><label>Valor investido</label><input name="invested" inputmode="decimal"></div><div class="field"><label>Valor atual</label><input name="current" inputmode="decimal"></div><button class="btn">Salvar investimento</button></form></section>`)}`}
function renderDebts(){const list=state.data.debts||[],open=list.filter(d=>n(d.saldoAtual)>0&&d.status!=='Quitada'),total=open.reduce((s,d)=>s+n(d.saldoAtual),0);return `${back()}${shell('Dívidas','Saldo, parcelas e pagamentos',`<div class="grid">${kpi('Em aberto',money(total),'pink')}${kpi('Dívidas',String(open.length),'cyan')}</div><section class="card">${list.length?list.map(d=>`${row(esc(d.credor||d.descricao||'Dívida'),money(d.saldoAtual),n(d.saldoAtual)>0?'pink':'green')}<div class="mini-meta">${esc(d.proximoVencimento||'Sem vencimento')} · ${esc(d.status||'Ativa')}</div>`).join(''):empty('Nenhuma dívida cadastrada.')}</section><section class="card"><h2 class="section-title">Nova dívida</h2><form id="debtForm" class="form"><div class="field"><label>Credor</label><input name="creditor" required></div><div class="field"><label>Descrição</label><input name="description"></div><div class="field"><label>Valor original</label><input name="original" inputmode="decimal" required></div><div class="field"><label>Saldo atual</label><input name="balance" inputmode="decimal"></div><div class="field"><label>Próximo vencimento</label><input name="due" type="date" value="${todayKey()}"></div><button class="btn">Salvar dívida</button></form></section>`)}`}
function tripStats(t){const items=(state.data.tripItems||[]).filter(i=>i.viagemId===t.id);const budget=n(t.orcamentoTotal??t.budget),reserved=n(t.valorReservado??t.reserved),paid=items.reduce((s,i)=>s+n(i.valorPago??i.paid),0);return{budget,reserved,paid,remaining:Math.max(budget-reserved-paid,0)}}
function renderTrips(){const list=state.data.trips||[];return `${back()}${shell('Viagens','Orçamento, reservas e planejamento',`<section class="card">${list.length?list.map(t=>{const s=tripStats(t);return `<div class="module-block"><strong>${esc(t.nome||'Viagem')}</strong><div class="mini-meta">${esc(t.destino||'Sem destino')} · ${esc(t.dataIda||'—')} → ${esc(t.dataVolta||'—')}</div>${row('Orçamento',money(s.budget))}${row('Reservado',money(s.reserved),'purple')}${row('Faltante',money(s.remaining),'pink')}</div>`}).join(''):empty('Nenhuma viagem cadastrada.')}</section><section class="card"><h2 class="section-title">Nova viagem</h2><form id="tripForm" class="form"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Destino</label><input name="destination"></div><div class="grid"><div class="field"><label>Ida</label><input name="start" type="date" value="${todayKey()}"></div><div class="field"><label>Volta</label><input name="end" type="date" value="${todayKey()}"></div></div><div class="field"><label>Orçamento</label><input name="budget" inputmode="decimal"></div><button class="btn">Salvar viagem</button></form></section>`)}`}
function invoiceTotal(card,ref){let total=0;for(const p of state.data.cardPurchases||[]){if(p.cartaoId!==card.id)continue;const count=Math.max(1,n(p.numeroParcelas)||1),first=p.primeiraFaturaRef||String(p.dataCompra||'').slice(0,7),value=n(p.valorTotal);for(let i=0;i<count;i++)if(addMonths(first,i)===ref)total+=value/count}return round2(total)}
function renderCards(){const ref=monthKey(),cards=(state.data.creditCards||[]).filter(c=>c.ativo!==false);return `${back()}${shell('Cartões','Faturas, compras e limite',`<section class="card">${cards.length?cards.map(c=>{const total=invoiceTotal(c,ref),limit=n(c.limiteTotal??c.limite);return `<div class="module-block"><strong>${esc(c.nome||'Cartão')}</strong><div class="mini-meta">vence dia ${esc(c.diaVencimento||'—')} · fecha dia ${esc(c.diaFechamento||'—')}</div>${row('Fatura do mês',money(total),'pink')}${row('Limite',money(limit))}${row('Disponível estimado',money(Math.max(limit-total,0)),'green')}</div>`}).join(''):empty('Nenhum cartão cadastrado.')}</section><section class="card"><h2 class="section-title">Novo cartão</h2><form id="cardForm" class="form"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Limite</label><input name="limit" inputmode="decimal"></div><div class="grid"><div class="field"><label>Fechamento</label><input name="closing" inputmode="numeric"></div><div class="field"><label>Vencimento</label><input name="due" inputmode="numeric"></div></div><button class="btn">Salvar cartão</button></form></section>`)}`}
function calendarRows(ref){const rows=[];for(const e of state.data.calendarEvents||[]){if(String(e.date||'').slice(0,7)===ref||e.recurringMonthly)rows.push({date:e.recurringMonthly?`${ref}-${String(Number(String(e.date||'').slice(8,10))||1).padStart(2,'0')}`:e.date,title:e.title||'Lembrete',category:e.category||'Lembrete',amount:n(e.amount)})}for(const p of state.data.priorities||[]){if(String(p.dataVencimento||'').slice(0,7)===ref)rows.push({date:p.dataVencimento,title:p.nome||'Prioridade',category:'Prioridade',amount:Math.max(n(p.valorPrevisto)-n(p.valorPago),0)})}for(const d of state.data.debts||[]){if(String(d.proximoVencimento||'').slice(0,7)===ref&&n(d.saldoAtual)>0)rows.push({date:d.proximoVencimento,title:`Dívida · ${d.credor||''}`,category:'Dívida',amount:n(d.valorParcela)||n(d.saldoAtual)})}for(const t of state.data.trips||[]){if(String(t.dataIda||'').slice(0,7)===ref)rows.push({date:t.dataIda,title:`Viagem · ${t.nome}`,category:'Viagem',amount:0})}return rows.sort((a,b)=>String(a.date).localeCompare(String(b.date)))}
function renderCalendar(){const ref=monthKey(),rows=calendarRows(ref);return `${back()}${shell('Calendário','Vencimentos, viagens e lembretes',`<div class="grid">${kpi('Eventos',String(rows.length),'cyan')}${kpi('Compromissos',money(rows.reduce((s,x)=>s+n(x.amount),0)),'pink')}</div><section class="card">${rows.length?rows.map(x=>`<div class="event-row"><div class="date-badge">${esc(String(x.date||'').slice(8,10))}</div><div class="main"><strong>${esc(x.title)}</strong><small>${esc(x.category)} · ${esc(x.date)}</small></div>${x.amount?`<b>${money(x.amount)}</b>`:''}</div>`).join(''):empty('Nenhum evento neste mês.')}</section><section class="card"><h2 class="section-title">Novo lembrete</h2><form id="calendarForm" class="form"><div class="field"><label>Título</label><input name="title" required></div><div class="field"><label>Data</label><input name="date" type="date" value="${todayKey()}"></div><div class="field"><label>Valor</label><input name="amount" inputmode="decimal"></div><button class="btn">Salvar lembrete</button></form></section>`)}`}
function categoryTotals(date=new Date()){const mk=monthKey(date),map={};for(const e of state.data.expenses||[]){if(String(e.date||e.data||'').slice(0,7)!==mk)continue;const c=e.category||e.categoria||'Outros';map[c]=(map[c]||0)+n(e.value??e.valor)}const fuel=(state.data.uberEntries||[]).filter(e=>String(e.date||'').slice(0,7)===mk&&e.active!==false).reduce((s,e)=>s+n(e.fuelExpense),0);if(fuel)map['Combustível Uber']=(map['Combustível Uber']||0)+fuel;return Object.entries(map).sort((a,b)=>b[1]-a[1])}
function renderReports(){const m=monthSummary(),cats=categoryTotals(),rows=movementRows().slice(0,8);return `${back()}${shell('Relatórios','Tendências, composição e desempenho',`<div class="grid">${kpi('Entradas',money(m.income),'green')}${kpi('Saídas',money(m.expenses),'pink')}${kpi('Resultado',money(m.result),m.result>=0?'cyan':'pink')}${kpi('Livre',money(m.free),'purple')}</div><section class="card"><h2 class="section-title">Saídas por categoria</h2>${cats.length?cats.map(([c,v])=>row(esc(c),money(v),'pink')).join(''):empty('Nenhuma saída neste mês.')}</section><section class="card"><h2 class="section-title">Últimos movimentos</h2>${rows.length?rows.map(r=>row(`${esc(r.date)} · ${esc(r.label)}`,`${r.kind==='income'?'+':'−'} ${money(r.value)}`,r.kind==='income'?'green':'pink')).join(''):empty('Nenhuma movimentação neste mês.')}</section>`)}`}
function renderProfile(){const profiles=state.data.profiles||[],active=activeProfile();return `${back()}${shell('Perfil','Quem está usando o Nexo agora',`<section class="card"><div class="profile-list">${profiles.length?profiles.map(p=>`<button class="profile-btn ${active?.id===p.id?'active':''}" data-profile="${esc(p.id)}"><span class="avatar">${esc(p.avatarEmoji||'N')}</span><span><strong>${esc(p.name||p.nome||'Perfil')}</strong><small style="display:block;color:var(--muted)">${active?.id===p.id?'Ativo':'Usar este perfil'}</small></span></button>`).join(''):empty('Perfis aparecerão após sincronizar.')}</div></section>`)}`}
function renderSettings(){return `${back()}${shell('Configurações','Supabase e conexão',`<section class="card"><h2 class="section-title">Banco central</h2><form id="configForm" class="form"><div class="field"><label>Project URL</label><input name="url" autocomplete="off" value="${esc(state.config.supabaseUrl||'')}"></div><div class="field"><label>Anon / public key</label><input name="anon" type="password" value="${esc(state.config.anonKey||'')}"></div><div class="field"><label>ID da família</label><input name="household" value="${esc(state.config.householdId||'')}"></div><div class="field"><label>Chave da família</label><input name="key" type="password" value="${esc(state.config.accessKey||'')}"></div><div id="configHint" class="notice">Os quatro campos são obrigatórios. Ao salvar, o Nexo testa a conexão e sincroniza imediatamente.</div><button class="btn">Salvar e testar conexão</button></form></section><section class="card"><h2 class="section-title">Instalar no iPhone</h2><div class="notice">No Safari: Compartilhar → <strong>Adicionar à Tela de Início</strong>.</div></section>`)}`}
function renderMore(){switch(state.morePage){case'cards':return renderCards();case'reports':return renderReports();case'priorities':return renderPriorities();case'investments':return renderInvestments();case'debts':return renderDebts();case'trips':return renderTrips();case'calendar':return renderCalendar();case'profile':return renderProfile();case'settings':return renderSettings();default:return renderMoreHub()}}
function render(){const a=activeProfile();document.getElementById('statusLine').textContent=`${a?.name||a?.nome||'Família'} · ${state.status}`;

/* ===== FASE 13I — PARIDADE PWA + DASHBOARD ===== */
state.tripDetailId=null;
state.cardDetailId=null;

function fmtDate(v){if(!v)return '—';const [y,m,d]=String(v).slice(0,10).split('-');return d?`${d}/${m}/${y}`:v}
function clamp(v,min,max){return Math.max(min,Math.min(max,v))}
function actionButtons(type,id,extra=''){return `<div class="item-actions"><button class="mini-btn" data-edit-type="${type}" data-edit-id="${esc(id)}">Editar</button>${extra}<button class="mini-btn danger-outline" data-delete-type="${type}" data-delete-id="${esc(id)}">Excluir</button></div>`}
function progressBar(value,total,label='Progresso'){const pct=total>0?clamp((value/total)*100,0,100):0;return `<div class="progress-wrap"><div class="progress-head"><span>${label}</span><strong>${pct.toFixed(0)}%</strong></div><div class="progress"><i style="width:${pct}%"></i></div></div>`}

function movementRows(date=new Date()){
  const mk=monthKey(date),rows=[];
  for(const e of state.data.uberEntries||[]){if(String(e.date||'').slice(0,7)!==mk||e.active===false)continue;rows.push({id:e.id,date:e.date,label:'Uber',kind:'income',value:n(e.value),sourceType:'uberEntries'});if(n(e.fuelExpense))rows.push({id:e.id,date:e.date,label:'Combustível Uber',kind:'expense',value:n(e.fuelExpense),sourceType:'uberFuel'})}
  for(const e of state.data.incomes||[]){if(String(e.date||e.data||'').slice(0,7)===mk)rows.push({id:e.id,date:e.date||e.data,label:e.description||e.descricao||e.category||e.categoria||'Entrada',kind:'income',value:n(e.value??e.valor),sourceType:'incomes'})}
  for(const e of state.data.expenses||[]){if(String(e.date||e.data||'').slice(0,7)===mk)rows.push({id:e.id,date:e.date||e.data,label:e.description||e.descricao||e.category||e.categoria||'Saída',kind:'expense',value:n(e.value??e.valor),sourceType:'expenses'})}
  return rows.sort((a,b)=>String(b.date).localeCompare(String(a.date)));
}
function dailyFlow(date=new Date()){
  const mk=monthKey(date),[y,m]=mk.split('-').map(Number),days=new Date(y,m,0).getDate(),vals=Array(days).fill(0);
  for(const r of movementRows(date)){const day=Number(String(r.date).slice(8,10));if(day>=1&&day<=days)vals[day-1]+=r.kind==='income'?r.value:-r.value}
  const cumulative=[];let acc=0;vals.forEach(v=>{acc+=v;cumulative.push(acc)});
  return cumulative;
}
function lineChart(){
  const vals=dailyFlow(),days=vals.length,today=new Date().getDate(),m=monthSummary(),actualEnd=Math.min(today,days)-1;
  const futureFinal=(vals[actualEnd]||0)-m.pending-m.reserved-m.planned;
  const projected=vals.slice();
  for(let i=actualEnd+1;i<days;i++){const t=(i-actualEnd)/(days-1-actualEnd||1);projected[i]=(vals[actualEnd]||0)+(futureFinal-(vals[actualEnd]||0))*t}
  const all=[...vals.slice(0,actualEnd+1),...projected.slice(actualEnd+1)],min=Math.min(0,...all),max=Math.max(0,...all),range=max-min||1,w=340,h=150,p=14;
  const pt=(v,i)=>`${p+(i/(days-1||1))*(w-p*2)},${h-p-((v-min)/range)*(h-p*2)}`;
  const actualPts=vals.slice(0,actualEnd+1).map(pt).join(' '),projPts=projected.slice(actualEnd).map((v,j)=>pt(v,j+actualEnd)).join(' ');
  const zeroY=h-p-((0-min)/range)*(h-p*2);
  return `<section class="card chart-card"><div class="chart-head"><div><span class="label">EVOLUÇÃO DO MÊS</span><strong>${money(vals[actualEnd]||0)}</strong></div><div class="legend"><span><i class="dot cyan-dot"></i>Realizado</span><span><i class="dot proj-dot"></i>Previsto</span></div></div><svg class="line-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="${p}" y1="${zeroY}" x2="${w-p}" y2="${zeroY}" class="zero-line"/><polyline points="${actualPts}" class="actual-line"/><polyline points="${projPts}" class="projected-line"/></svg><div class="chart-axis"><span>1</span><span>${Math.ceil(days/2)}</span><span>${days}</span></div></section>`
}
function donutChart(){
  const cats=categoryTotals().slice(0,5),total=cats.reduce((s,x)=>s+x[1],0);if(!total)return `<section class="card"><h2 class="section-title">Despesas por categoria</h2>${empty('Ainda não há saídas neste mês.')}</section>`;
  const colors=['#09d7ee','#89e51d','#a36cff','#ef3386','#f6b73c'],r=48,c=2*Math.PI*r;let offset=0;
  const circles=cats.map(([name,val],i)=>{const len=c*val/total,el=`<circle cx="60" cy="60" r="${r}" fill="none" stroke="${colors[i]}" stroke-width="18" stroke-dasharray="${len} ${c-len}" stroke-dashoffset="${-offset}"/>`;offset+=len;return el}).join('');
  return `<section class="card"><h2 class="section-title">Despesas por categoria</h2><div class="donut-layout"><svg viewBox="0 0 120 120" class="donut"><g transform="rotate(-90 60 60)">${circles}</g><text x="60" y="57" text-anchor="middle" class="donut-total">${esc(money(total).replace(/\s/g,' '))}</text><text x="60" y="72" text-anchor="middle" class="donut-sub">Total</text></svg><div class="cat-legend">${cats.map(([name,val],i)=>`<div><i style="background:${colors[i]}"></i><span>${esc(name)}</span><strong>${Math.round(val/total*100)}%</strong></div>`).join('')}</div></div></section>`
}
function renderHome(){const m=monthSummary();return shell('Visão Geral','Seu mês em uma leitura rápida',`<section class="balance-hero"><span>Resultado realizado</span><strong class="${m.result>=0?'green':'pink'}">${money(m.result)}</strong><div><b>Entradas ${money(m.income)}</b><b>Saídas ${money(m.expenses)}</b></div></section>${lineChart()}<section class="card compact-overview"><h2 class="section-title">Visão geral</h2>${row('Receitas',money(m.income),'green')}${row('Despesas',money(m.expenses),'pink')}${row('Prioridades pendentes',money(m.pending),'purple')}${row('Faturas do mês',money((state.data.creditCards||[]).reduce((s,c)=>s+invoiceTotal(c,m.mk),0)),'cyan')}</section>${donutChart()}`)}

function renderMoves(){const rows=movementRows();return shell('Movimentos','Entradas e saídas reais do mês',`<section class="card">${rows.length?rows.map(r=>`<div class="movement"><div class="main"><strong>${esc(r.label)}</strong><small>${fmtDate(r.date)}</small></div><div class="amount ${r.kind==='income'?'green':'pink'}">${r.kind==='income'?'+':'−'} ${money(r.value)}</div>${r.sourceType==='incomes'||r.sourceType==='expenses'?`<button class="dots-btn" data-edit-type="${r.sourceType}" data-edit-id="${esc(r.id)}">•••</button>`:''}</div>`).join(''):empty('Nenhuma movimentação neste mês.')}</section><section class="card"><h2 class="section-title">Novo lançamento</h2><form id="movementForm" class="form"><div class="field"><label>Tipo</label><select name="type"><option value="expense">Saída</option><option value="income">Entrada</option></select></div><div class="field"><label>Descrição</label><input name="description" required></div><div class="field"><label>Valor</label><input name="value" inputmode="decimal" required></div><div class="field"><label>Data</label><input name="date" type="date" value="${todayKey()}" required></div><button class="btn">Salvar e sincronizar</button></form></section>`)}

function renderPriorities(){const ref=monthKey(),list=(state.data.priorities||[]).filter(x=>String(x.dataVencimento||'').slice(0,7)===ref||String(x.mesReferencia||'')===ref||`${x.anoReferencia}-${String(x.mesReferencia).padStart(2,'0')}`===ref);const pending=list.reduce((s,x)=>s+Math.max(n(x.valorPrevisto)-n(x.valorPago),0),0);return `${back()}${shell('Prioridades','Compromissos antes do dinheiro livre',`<div class="grid">${kpi('Pendentes',money(pending),'pink')}${kpi('Itens',String(list.length),'cyan')}</div><section class="card">${list.length?list.map(x=>{const total=n(x.valorPrevisto),done=n(x.valorPago)+n(x.valorReservado);return `<div class="module-block"><strong>${esc(x.nome||'Prioridade')}</strong><div class="mini-meta">${fmtDate(x.dataVencimento)} · ${esc(x.nivelPrioridade||'')}</div>${row('Previsto',money(total))}${row('Pago / reservado',money(done),'green')}${progressBar(done,total,'Cobertura')}${actionButtons('priorities',x.id)}</div>`}).join(''):empty('Nenhuma prioridade neste mês.')}</section><section class="card"><h2 class="section-title">Nova prioridade</h2><form id="priorityForm" class="form"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Valor previsto</label><input name="value" inputmode="decimal" required></div><div class="field"><label>Vencimento</label><input name="due" type="date" value="${todayKey()}"></div><button class="btn">Salvar prioridade</button></form></section>`)}`}

function renderInvestments(){const list=(state.data.investments||[]).filter(x=>x.ativo!==false),divs=state.data.dividends||[];let invested=0,current=0;list.forEach(x=>{const s=investmentSummary(x);invested+=s.invested;current+=s.current});const yields=divs.reduce((s,d)=>s+n(d.valor),0);return `${back()}${shell('Investimentos','Patrimônio e rendimentos',`<div class="grid">${kpi('Investido',money(invested),'cyan')}${kpi('Atual',money(current),'green')}${kpi('Resultado',money(current-invested),current>=invested?'green':'pink')}${kpi('Rendimentos',money(yields),'purple')}</div><section class="card">${list.length?list.map(x=>{const s=investmentSummary(x);return `<div class="module-block"><strong>${esc(x.nome||x.ticker||'Investimento')}</strong><div class="mini-meta">${esc(x.ticker||x.tipo||'')} · investido ${money(s.invested)}</div>${row('Valor atual',money(s.current),'cyan')}${actionButtons('investments',x.id)}</div>`}).join(''):empty('Nenhum investimento cadastrado.')}</section><section class="card"><h2 class="section-title">Novo investimento</h2><form id="investmentForm" class="form"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Ticker</label><input name="ticker"></div><div class="field"><label>Tipo</label><select name="type"><option>FII</option><option>Ação</option><option>ETF</option><option>Tesouro Direto</option><option>CDB</option><option>Criptomoeda</option><option>Outro</option></select></div><div class="field"><label>Valor investido</label><input name="invested" inputmode="decimal"></div><div class="field"><label>Valor atual</label><input name="current" inputmode="decimal"></div><button class="btn">Salvar investimento</button></form></section>`)}`}

function renderDebts(){const list=state.data.debts||[],open=list.filter(d=>n(d.saldoAtual)>0&&d.status!=='Quitada'),total=open.reduce((s,d)=>s+n(d.saldoAtual),0);return `${back()}${shell('Dívidas','Saldo, parcelas e pagamentos',`<div class="grid">${kpi('Em aberto',money(total),'pink')}${kpi('Dívidas',String(open.length),'cyan')}</div><section class="card">${list.length?list.map(d=>`<div class="module-block"><strong>${esc(d.credor||d.descricao||'Dívida')}</strong><div class="mini-meta">${fmtDate(d.proximoVencimento)} · ${esc(d.status||'Ativa')}</div>${row('Saldo',money(d.saldoAtual),n(d.saldoAtual)>0?'pink':'green')}${progressBar(Math.max(n(d.valorOriginal)-n(d.saldoAtual),0),n(d.valorOriginal),'Quitado')}${actionButtons('debts',d.id)}</div>`).join(''):empty('Nenhuma dívida cadastrada.')}</section><section class="card"><h2 class="section-title">Nova dívida</h2><form id="debtForm" class="form"><div class="field"><label>Credor</label><input name="creditor" required></div><div class="field"><label>Descrição</label><input name="description"></div><div class="field"><label>Valor original</label><input name="original" inputmode="decimal" required></div><div class="field"><label>Saldo atual</label><input name="balance" inputmode="decimal"></div><div class="field"><label>Próximo vencimento</label><input name="due" type="date" value="${todayKey()}"></div><button class="btn">Salvar dívida</button></form></section>`)}`}

function renderTripDetail(t){const s=tripStats(t),items=(state.data.tripItems||[]).filter(i=>String(i.viagemId||i.tripId)===String(t.id)),covered=s.reserved+s.paid;return `${back()}<button class="back-link" data-trip-back>‹ Todas as viagens</button>${shell(t.nome||'Viagem',`${t.destino||'Destino'} · ${fmtDate(t.dataIda)} → ${fmtDate(t.dataVolta)}`,`<section class="card">${row('Orçamento',money(s.budget))}${row('Reservado',money(s.reserved),'purple')}${row('Pago',money(s.paid),'green')}${row('Faltante',money(s.remaining),'pink')}${progressBar(covered,s.budget,'Planejamento financeiro')}${actionButtons('trips',t.id)}</section><section class="card"><h2 class="section-title">Passagens, hospedagens e gastos</h2>${items.length?items.map(i=>`<div class="module-block"><strong>${esc(i.descricao||i.nome||i.tipo||'Item')}</strong><div class="mini-meta">${esc(i.tipo||i.categoria||'Outros')} · ${fmtDate(i.data||i.dataPagamento)}</div>${row('Previsto',money(i.valorPrevisto??i.valor??i.value))}${row('Pago',money(i.valorPago??i.paid),'green')}${actionButtons('tripItems',i.id)}</div>`).join(''):empty('Nenhum item adicionado.')}</section><section class="card"><h2 class="section-title">Adicionar item</h2><form id="tripItemForm" class="form"><input type="hidden" name="tripId" value="${esc(t.id)}"><div class="field"><label>Tipo</label><select name="type"><option>Passagem</option><option>Hospedagem</option><option>Alimentação</option><option>Transporte</option><option>Passeio</option><option>Seguro</option><option>Outros</option></select></div><div class="field"><label>Descrição</label><input name="description" required></div><div class="grid"><div class="field"><label>Valor previsto</label><input name="value" inputmode="decimal"></div><div class="field"><label>Valor pago</label><input name="paid" inputmode="decimal"></div></div><div class="field"><label>Data</label><input name="date" type="date" value="${todayKey()}"></div><button class="btn">Adicionar à viagem</button></form></section>`)}`}
function renderTrips(){const list=state.data.trips||[];if(state.tripDetailId){const t=list.find(x=>String(x.id)===String(state.tripDetailId));if(t)return renderTripDetail(t);state.tripDetailId=null}return `${back()}${shell('Viagens','Orçamento, reservas e planejamento',`<section class="card">${list.length?list.map(t=>{const s=tripStats(t),covered=s.reserved+s.paid;return `<div class="module-block"><strong>${esc(t.nome||'Viagem')}</strong><div class="mini-meta">${esc(t.destino||'Sem destino')} · ${fmtDate(t.dataIda)} → ${fmtDate(t.dataVolta)}</div>${row('Orçamento',money(s.budget))}${row('Faltante',money(s.remaining),'pink')}${progressBar(covered,s.budget,'Progresso')}<div class="item-actions"><button class="mini-btn primary-mini" data-trip-detail="${esc(t.id)}">Ver mais</button><button class="mini-btn" data-edit-type="trips" data-edit-id="${esc(t.id)}">Editar</button><button class="mini-btn danger-outline" data-delete-type="trips" data-delete-id="${esc(t.id)}">Excluir</button></div></div>`}).join(''):empty('Nenhuma viagem cadastrada.')}</section><section class="card"><h2 class="section-title">Nova viagem</h2><form id="tripForm" class="form"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Destino</label><input name="destination"></div><div class="grid"><div class="field"><label>Ida</label><input name="start" type="date" value="${todayKey()}"></div><div class="field"><label>Volta</label><input name="end" type="date" value="${todayKey()}"></div></div><div class="field"><label>Orçamento</label><input name="budget" inputmode="decimal"></div><button class="btn">Salvar viagem</button></form></section>`)}`}

function cardPurchases(cardId){return (state.data.cardPurchases||[]).filter(p=>String(p.cartaoId||p.cardId)===String(cardId))}
function renderCardDetail(c){const ref=monthKey(),total=invoiceTotal(c,ref),limit=n(c.limiteTotal??c.limite),purchases=cardPurchases(c.id);return `${back()}<button class="back-link" data-card-back>‹ Todos os cartões</button>${shell(c.nome||'Cartão',`Fecha dia ${c.diaFechamento||'—'} · vence dia ${c.diaVencimento||'—'}`,`<div class="grid">${kpi('Fatura',money(total),'pink')}${kpi('Disponível',money(Math.max(limit-total,0)),'green')}</div><section class="card">${actionButtons('creditCards',c.id)}</section><section class="card"><h2 class="section-title">Compras / parcelas</h2>${purchases.length?purchases.map(p=>`<div class="module-block"><strong>${esc(p.descricao||p.nome||'Compra')}</strong><div class="mini-meta">${fmtDate(p.dataCompra||p.date)} · ${n(p.numeroParcelas)||1}x</div>${row('Valor total',money(p.valorTotal??p.valor??p.value),'pink')}${actionButtons('cardPurchases',p.id)}</div>`).join(''):empty('Nenhuma compra neste cartão.')}</section><section class="card"><h2 class="section-title">Nova compra</h2><form id="cardPurchaseForm" class="form"><input type="hidden" name="cardId" value="${esc(c.id)}"><div class="field"><label>Descrição</label><input name="description" required></div><div class="grid"><div class="field"><label>Valor total</label><input name="value" inputmode="decimal" required></div><div class="field"><label>Parcelas</label><input name="installments" inputmode="numeric" value="1"></div></div><div class="field"><label>Data da compra</label><input name="date" type="date" value="${todayKey()}"></div><button class="btn">Adicionar compra</button></form></section>`)}`}
function renderCards(){const ref=monthKey(),cards=(state.data.creditCards||[]).filter(c=>c.ativo!==false);if(state.cardDetailId){const c=cards.find(x=>String(x.id)===String(state.cardDetailId));if(c)return renderCardDetail(c);state.cardDetailId=null}return `${back()}${shell('Cartões','Faturas, compras e limite',`<section class="card">${cards.length?cards.map(c=>{const total=invoiceTotal(c,ref),limit=n(c.limiteTotal??c.limite);return `<div class="module-block"><strong>${esc(c.nome||'Cartão')}</strong><div class="mini-meta">vence dia ${esc(c.diaVencimento||'—')} · fecha dia ${esc(c.diaFechamento||'—')}</div>${row('Fatura do mês',money(total),'pink')}${row('Disponível estimado',money(Math.max(limit-total,0)),'green')}<div class="item-actions"><button class="mini-btn primary-mini" data-card-detail="${esc(c.id)}">Ver fatura</button><button class="mini-btn" data-edit-type="creditCards" data-edit-id="${esc(c.id)}">Editar</button><button class="mini-btn danger-outline" data-delete-type="creditCards" data-delete-id="${esc(c.id)}">Excluir</button></div></div>`}).join(''):empty('Nenhum cartão cadastrado.')}</section><section class="card"><h2 class="section-title">Novo cartão</h2><form id="cardForm" class="form"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Limite</label><input name="limit" inputmode="decimal"></div><div class="grid"><div class="field"><label>Fechamento</label><input name="closing" inputmode="numeric"></div><div class="field"><label>Vencimento</label><input name="due" inputmode="numeric"></div></div><button class="btn">Salvar cartão</button></form></section>`)}`}

function renderCalendar(){const list=(state.data.calendarEvents||[]).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));return `${back()}${shell('Calendário','Vencimentos e lembretes',`<section class="card">${list.length?list.map(e=>`<div class="event-row"><div class="date-badge">${esc(String(e.date||'').slice(8,10)||'—')}</div><div class="main"><strong>${esc(e.title||e.titulo||'Evento')}</strong><small>${fmtDate(e.date)} · ${esc(e.category||e.categoria||'Lembrete')}</small></div>${n(e.amount)?`<b>${money(e.amount)}</b>`:''}<button class="dots-btn" data-edit-type="calendarEvents" data-edit-id="${esc(e.id)}">•••</button></div>`).join(''):empty('Nenhum evento cadastrado.')}</section><section class="card"><h2 class="section-title">Novo lembrete</h2><form id="calendarForm" class="form"><div class="field"><label>Título</label><input name="title" required></div><div class="field"><label>Data</label><input name="date" type="date" value="${todayKey()}"></div><div class="field"><label>Valor</label><input name="amount" inputmode="decimal"></div><button class="btn">Salvar lembrete</button></form></section>`)}`}

function shortcutOf(){return activeProfile()?.mainShortcut||activeProfile()?.atalhoPrincipal||'uber'}
const shortcutMap={uber:{label:'Uber',icon:'car-front'},cards:{label:'Cartões',icon:'credit-card'},priorities:{label:'Prioridades',icon:'siren'},trips:{label:'Viagens',icon:'plane'},investments:{label:'Investir',icon:'chart-no-axes-combined'}};
function renderProfile(){const profiles=state.data.profiles||[],active=activeProfile(),shortcut=shortcutOf();return `${back()}${shell('Perfil','Quem está usando o Nexo agora',`<section class="card"><div class="profile-list">${profiles.length?profiles.map(p=>`<button class="profile-btn ${active?.id===p.id?'active':''}" data-profile="${esc(p.id)}"><span class="avatar">${esc(p.avatarEmoji||'N')}</span><span><strong>${esc(p.name||p.nome||'Perfil')}</strong><small style="display:block;color:var(--muted)">${active?.id===p.id?'Ativo':'Usar este perfil'}</small></span></button>`).join(''):empty('Perfis aparecerão após sincronizar.')}</div></section>${active?`<section class="card"><h2 class="section-title">Atalho principal</h2><p class="subtitle small-sub">O botão central da barra pode ser diferente para cada perfil.</p><div class="shortcut-grid">${Object.entries(shortcutMap).map(([key,v])=>`<button class="shortcut-btn ${shortcut===key?'active':''}" data-shortcut="${key}"><img src="assets/icons/${v.icon}.svg"><span>${v.label}</span></button>`).join('')}</div></section>`:''}`)}`}

function render(){
  const a=activeProfile(),shortcut=shortcutOf(),meta=shortcutMap[shortcut]||shortcutMap.uber,third=document.querySelector('.bottom-nav button:nth-child(3)');
  if(third){third.dataset.tab=shortcut;third.innerHTML=`<img src="assets/icons/${meta.icon}.svg" alt=""><span>${meta.label}</span>`}
  document.getElementById('statusLine').textContent=`${a?.name||a?.nome||'Família'} · ${state.status}`;
  document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));
  const map={home:renderHome,moves:renderMoves,uber:renderUber,assistant:renderAssistant,cards:renderCards,priorities:renderPriorities,trips:renderTrips,investments:renderInvestments};
  const content=document.getElementById('content');content.innerHTML=(map[state.tab]||renderMore)();bindPage();
}

function findRecord(type,id){return (state.data[type]||[]).find(x=>String(x.id)===String(id))}
function editorFields(type,r){
  const schemas={
    incomes:[['description','Descrição','text',r.description||r.descricao],['value','Valor','number',r.value??r.valor],['date','Data','date',r.date||r.data]],
    expenses:[['description','Descrição','text',r.description||r.descricao],['value','Valor','number',r.value??r.valor],['date','Data','date',r.date||r.data]],
    priorities:[['nome','Nome','text',r.nome],['valorPrevisto','Valor previsto','number',r.valorPrevisto],['valorReservado','Reservado','number',r.valorReservado],['valorPago','Pago','number',r.valorPago],['dataVencimento','Vencimento','date',r.dataVencimento]],
    investments:[['nome','Nome','text',r.nome],['ticker','Ticker','text',r.ticker],['valorInvestido','Valor investido','number',r.valorInvestido],['valorAtual','Valor atual','number',r.valorAtual]],
    debts:[['credor','Credor','text',r.credor],['descricao','Descrição','text',r.descricao],['valorOriginal','Valor original','number',r.valorOriginal],['saldoAtual','Saldo atual','number',r.saldoAtual],['proximoVencimento','Próximo vencimento','date',r.proximoVencimento]],
    trips:[['nome','Nome','text',r.nome],['destino','Destino','text',r.destino],['dataIda','Ida','date',r.dataIda],['dataVolta','Volta','date',r.dataVolta],['orcamentoTotal','Orçamento','number',r.orcamentoTotal],['valorReservado','Reservado','number',r.valorReservado]],
    tripItems:[['tipo','Tipo','text',r.tipo||r.categoria],['descricao','Descrição','text',r.descricao||r.nome],['valorPrevisto','Valor previsto','number',r.valorPrevisto??r.valor],['valorPago','Valor pago','number',r.valorPago],['data','Data','date',r.data||r.dataPagamento]],
    creditCards:[['nome','Nome','text',r.nome],['limiteTotal','Limite','number',r.limiteTotal??r.limite],['diaFechamento','Fechamento','number',r.diaFechamento],['diaVencimento','Vencimento','number',r.diaVencimento]],
    cardPurchases:[['descricao','Descrição','text',r.descricao||r.nome],['valorTotal','Valor total','number',r.valorTotal??r.valor],['numeroParcelas','Parcelas','number',r.numeroParcelas],['dataCompra','Data da compra','date',r.dataCompra]],
    calendarEvents:[['title','Título','text',r.title||r.titulo],['date','Data','date',r.date],['amount','Valor','number',r.amount]]
  };return schemas[type]||[]
}
function openEditor(type,id){const r=findRecord(type,id);if(!r)return;const fields=editorFields(type,r);if(!fields.length)return;const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="modal"><div class="modal-head"><strong>Editar</strong><button data-modal-close>×</button></div><form id="genericEditForm" class="form" data-type="${type}" data-id="${esc(id)}">${fields.map(([key,label,input,val])=>`<div class="field"><label>${label}</label><input name="${key}" type="${input==='number'?'text':input}" inputmode="${input==='number'?'decimal':''}" value="${esc(val??'')}"></div>`).join('')}<button class="btn">Salvar alterações</button><button type="button" class="btn danger" data-delete-type="${type}" data-delete-id="${esc(id)}">Excluir</button></form></div>`;document.body.appendChild(modal)}

async function saveGenericEdit(form){if(!ensureConnected())return;const type=form.dataset.type,id=form.dataset.id,r=findRecord(type,id),f=new FormData(form),next={...r};for(const [key,,kind] of editorFields(type,r)){const v=f.get(key);next[key]=kind==='number'?n(v):v}next.updatedAt=new Date().toISOString();await upsert(type,id,recordMeta({...next,createdAt:r.createdAt}));document.querySelector('.modal-backdrop')?.remove()}

/* Delegação adicional da fase 13I */
document.addEventListener('click',async e=>{
  const close=e.target.closest('[data-modal-close]');if(close){close.closest('.modal-backdrop')?.remove();return}
  const edit=e.target.closest('[data-edit-type]');if(edit){openEditor(edit.dataset.editType,edit.dataset.editId);return}
  const del=e.target.closest('[data-delete-type]');if(del){const type=del.dataset.deleteType,id=del.dataset.deleteId;if(confirm('Excluir este registro? Esta ação será sincronizada.')){await removeRecord(type,id);document.querySelector('.modal-backdrop')?.remove()}return}
  const td=e.target.closest('[data-trip-detail]');if(td){state.tripDetailId=td.dataset.tripDetail;state.tab='more';state.morePage='trips';render();scrollTo({top:0,behavior:'smooth'});return}
  if(e.target.closest('[data-trip-back]')){state.tripDetailId=null;render();return}
  const cd=e.target.closest('[data-card-detail]');if(cd){state.cardDetailId=cd.dataset.cardDetail;state.tab='more';state.morePage='cards';render();scrollTo({top:0,behavior:'smooth'});return}
  if(e.target.closest('[data-card-back]')){state.cardDetailId=null;render();return}
  const sh=e.target.closest('[data-shortcut]');if(sh){const p=activeProfile();if(!p||!ensureConnected())return;const next={...p,mainShortcut:sh.dataset.shortcut,atalhoPrincipal:sh.dataset.shortcut,updatedAt:new Date().toISOString()};await upsert('profiles',p.id,next);state.profileId=p.id;render();return}
});
document.addEventListener('submit',async e=>{
  if(e.target.id==='genericEditForm'){e.preventDefault();await saveGenericEdit(e.target);return}
  if(e.target.id==='tripItemForm'){e.preventDefault();if(!ensureConnected())return;const f=new FormData(e.target),id=uuid();await upsert('tripItems',id,recordMeta({id,viagemId:f.get('tripId'),tipo:f.get('type'),descricao:String(f.get('description')).trim(),valorPrevisto:n(f.get('value')),valorPago:n(f.get('paid')),data:f.get('date')}));return}
  if(e.target.id==='cardPurchaseForm'){e.preventDefault();if(!ensureConnected())return;const f=new FormData(e.target),id=uuid(),date=f.get('date');await upsert('cardPurchases',id,recordMeta({id,cartaoId:f.get('cardId'),descricao:String(f.get('description')).trim(),valorTotal:n(f.get('value')),numeroParcelas:Math.max(1,Math.round(n(f.get('installments'))||1)),dataCompra:date,primeiraFaturaRef:String(date).slice(0,7)}));return}
});

document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));const content=document.getElementById('content');content.innerHTML=state.tab==='home'?renderHome():state.tab==='moves'?renderMoves():state.tab==='uber'?renderUber():state.tab==='assistant'?renderAssistant():renderMore();bindPage()}
function ensureConnected(){if(validConfig(state.config))return true;alert(`Falta configurar: ${configProblems(state.config).join(', ')}.`);state.tab='more';state.morePage='settings';render();return false}
function bindPage(){document.querySelectorAll('[data-more]').forEach(b=>b.addEventListener('click',()=>{state.morePage=b.dataset.more;render();scrollTo({top:0,behavior:'smooth'})}));document.querySelectorAll('[data-profile]').forEach(b=>b.addEventListener('click',()=>{state.profileId=b.dataset.profile;saveLocal();render()}));document.getElementById('movementForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!ensureConnected())return;const f=new FormData(e.currentTarget),type=f.get('type'),id=uuid();await upsert(type==='income'?'incomes':'expenses',id,recordMeta({id,date:f.get('date'),description:f.get('description'),category:'Outros',value:n(f.get('value'))}))});document.getElementById('uberForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!ensureConnected())return;const f=new FormData(e.currentTarget),date=f.get('date'),existing=(state.data.uberEntries||[]).find(x=>x.date===date),id=existing?.id||uuid(),gross=n(f.get('gross')),pct=n(f.get('pct'));await upsert('uberEntries',id,recordMeta({...existing,id,date,value:gross,active:true,fuelExpense:n(f.get('fuel')),kmDriven:n(f.get('km')),reservePercent:pct,reserveValue:gross*pct/100,createdAt:existing?.createdAt}))});document.getElementById('assistantForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),text=String(f.get('text')||'').trim();if(!text)return;state.assistant.push({role:'user',text});const p=parseAssistant(text);if(p.error){state.assistant.push({role:'bot',text:p.error});return render()}if(!ensureConnected())return;const ok=confirm(`${p.type==='income'?'Registrar entrada':'Registrar saída'} de ${money(p.value)} em ${p.date}?\n\n${p.description}`);if(ok){const id=uuid();await upsert(p.type==='income'?'incomes':'expenses',id,recordMeta({id,date:p.date,description:p.description,category:'Outros',value:p.value}));state.assistant.push({role:'bot',text:'Lançamento registrado e sincronizado.'})}render()});document.getElementById('configForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);state.config={supabaseUrl:normalizeUrl(f.get('url')),anonKey:String(f.get('anon')||'').trim(),householdId:String(f.get('household')||'').trim(),accessKey:String(f.get('key')||'').trim()};saveLocal();const missing=configProblems(state.config);if(missing.length){alert(`Revise: ${missing.join(', ')}.`);return}const ok=await sync();if(ok)alert('Conexão OK. Dados sincronizados com o Supabase.')});document.getElementById('priorityForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!ensureConnected())return;const f=new FormData(e.currentTarget),id=uuid(),d=String(f.get('due')||todayKey()),[y,m]=d.split('-').map(Number);await upsert('priorities',id,recordMeta({id,nome:String(f.get('name')).trim(),categoria:'Outros compromissos',valorPrevisto:n(f.get('value')),valorReservado:0,valorPago:0,dataVencimento:d,nivelPrioridade:'Alta',mesReferencia:m,anoReferencia:y,recorrente:false}))});document.getElementById('investmentForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!ensureConnected())return;const f=new FormData(e.currentTarget),id=uuid();await upsert('investments',id,recordMeta({id,nome:String(f.get('name')).trim(),ticker:String(f.get('ticker')).trim(),tipo:f.get('type'),valorInvestido:n(f.get('invested')),valorAtual:n(f.get('current')),ativo:true,dataPrimeiroAporte:todayKey()}))});document.getElementById('debtForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!ensureConnected())return;const f=new FormData(e.currentTarget),id=uuid(),orig=n(f.get('original')),bal=String(f.get('balance')).trim()?n(f.get('balance')):orig;await upsert('debts',id,recordMeta({id,credor:String(f.get('creditor')).trim(),descricao:String(f.get('description')).trim(),valorOriginal:orig,saldoAtual:bal,proximoVencimento:f.get('due'),status:bal<=0?'Quitada':'Ativa'}))});document.getElementById('tripForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!ensureConnected())return;const f=new FormData(e.currentTarget),id=uuid();await upsert('trips',id,recordMeta({id,nome:String(f.get('name')).trim(),destino:String(f.get('destination')).trim(),dataIda:f.get('start'),dataVolta:f.get('end'),orcamentoTotal:n(f.get('budget')),valorReservado:0,status:'Planejada'}))});document.getElementById('cardForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!ensureConnected())return;const f=new FormData(e.currentTarget),id=uuid();await upsert('creditCards',id,recordMeta({id,nome:String(f.get('name')).trim(),limiteTotal:n(f.get('limit')),diaFechamento:n(f.get('closing')),diaVencimento:n(f.get('due')),ativo:true}))});document.getElementById('calendarForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!ensureConnected())return;const f=new FormData(e.currentTarget),id=uuid();await upsert('calendarEvents',id,recordMeta({id,title:String(f.get('title')).trim(),date:f.get('date'),category:'Lembrete',amount:n(f.get('amount')),recurringMonthly:false}))})}
document.querySelectorAll('.bottom-nav button').forEach(b=>b.addEventListener('click',()=>{state.tab=b.dataset.tab;if(state.tab==='more'&&state.morePage!=='hub')state.morePage='hub';render();scrollTo({top:0,behavior:'smooth'})}));document.getElementById('syncBtn').addEventListener('click',()=>sync());
loadLocal();render();if(validConfig(state.config))sync(true);
setTimeout(()=>{document.getElementById('splash').classList.add('hidden');document.getElementById('app').classList.remove('hidden')},1200);
if('serviceWorker' in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
